import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int L = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());

        char[][] map = new char[L][C];
        for (int i = 0; i < L; i++) {
            String line = br.readLine();
            if (line == null) line = "";
            int len = Math.min(line.length(), C);
            for (int j = 0; j < len; j++) {
                map[i][j] = line.charAt(j);
            }
        }

        int startR = -1, startC = -1;
        outer:
        for (int i = 0; i < L; i++) {
            for (int j = 0; j < C; j++) {
                if (map[i][j] == 'o') {
                    startR = i;
                    startC = j;
                    break outer;
                }
            }
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // As garantias do problema implicam que:
        // - a posição inicial ('o') tem exatamente 1 vizinho 'H' (o próximo passo do caminho);
        // - cada posição intermediária tem exatamente 2 vizinhos 'H' (anterior e próximo),
        //   logo nenhum 'H' de erro é adjacente ao caminho;
        // - a posição final tem exatamente 1 vizinho 'H' (o anterior).
        // Portanto basta caminhar a partir do 'o', sempre indo para o único
        // vizinho 'H' diferente da célula anterior.
        int curR = startR, curC = startC;
        int prevR = -1, prevC = -1;

        while (true) {
            int nextR = -1, nextC = -1;
            for (int d = 0; d < 4; d++) {
                int nr = curR + dr[d];
                int nc = curC + dc[d];
                if (nr < 0 || nr >= L || nc < 0 || nc >= C) continue;
                if (map[nr][nc] != 'H') continue;
                if (nr == prevR && nc == prevC) continue;
                nextR = nr;
                nextC = nc;
                break;
            }
            if (nextR == -1) break; // célula atual é a posição atual de Hermione
            prevR = curR;
            prevC = curC;
            curR = nextR;
            curC = nextC;
        }

        System.out.println((curR + 1) + " " + (curC + 1));
    }
}
